/* The generated tables must stay the same length as the enum in
 * kws_model.h. A mismatch means the checkpoint changed shape without
 * the firmware enum being updated, which would silently read the
 * wrong weights. */
_Static_assert(sizeof(kws_tensors) / sizeof(kws_tensors[0])
               == KWS_NUM_TENSORS,
              "kws_tensors length != KWS_NUM_TENSORS");
_Static_assert(sizeof(kws_param_off) / sizeof(kws_param_off[0])
               == KWS_NUM_TENSORS, "kws_param_off length");
_Static_assert(sizeof(kws_wscale) / sizeof(kws_wscale[0])
               == KWS_NUM_TENSORS, "kws_wscale length");
